  void Log(string message) {if(closed||Get<TextBox>("LogText")==null)return;string clean=message;if(api!=null&&api.Key.Length>0)clean=clean.Replace(api.Key,"[密钥已隐藏]");logLines.Add(DateTime.Now.ToString("HH:mm:ss")+"  "+clean);if(logLines.Count>1500)logLines.RemoveRange(0,logLines.Count-1500);Get<TextBox>("LogText").Text=string.Join(Environment.NewLine,logLines);Get<TextBox>("LogText").ScrollToEnd();}
