   On("AutoLinkVideo",(s,e)=>RefreshVideoLinks(true));On("PrevSrt",(s,e)=>MoveSubtitle(-1));On("NextSrt",(s,e)=>MoveSubtitle(1));On("LocateCue",(s,e)=> {var cue=Get<DataGrid>("Cues").SelectedItem as Cue;if(cue!=null)ShowCue(cue,Get<DataGrid>("SubtitleIssues").SelectedItem as SubtitleIssue);});On("OpenVideoPage",(s,e)=> {var cue=Get<DataGrid>("Cues").SelectedItem as Cue;if(current!=null&&!string.IsNullOrEmpty(current.VideoPath)&&OpenVideoRequested!=null)OpenVideoRequested(current.VideoPath,cue==null?0:cue.Start);});On("ClearAllSrt",(s,e)=> {if(IsBusy)return;files.Clear();undo.Clear();current=null;Select(null);Get<TextBlock>("CueOriginal").Text="原文：—";Get<TextBlock>("CueSuggestion").Text="建议：—";Get<TextBlock>("CueEvidence").Text="剧本出处：—";logLines.Clear();Get<TextBox>("LogText").Clear();SetProgress(0,1,"已清空字幕");Status("已清空全部字幕、校对结果与修改记录；保留剧本、名词表和 API 设置。");});
   On("UndoChange",(s,e)=>UndoLast());On("PreviewChanges",(s,e)=>ShowChanges());On("ViewSource",(s,e)=> {var issue=Get<DataGrid>("SubtitleIssues").SelectedItem as SubtitleIssue;var w=FrameWindows.Dialog(owner,"剧本出处",780,530);w.Content=new TextBox {Text=(issue==null?"请选择名词疑点":issue.Evidence)+"\r\n\r\n原剧本："+scriptPath+"\r\n\r\n"+script,IsReadOnly=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Margin=new Thickness(12)};w.Show();});
   On("ClearLog",(s,e)=> {logLines.Clear();Get<TextBox>("LogText").Clear();NotifyChanged();});On("ExportLog",(s,e)=> {var d=new SaveFileDialog {Title="保存校对日志",Filter="日志文本|*.txt",FileName="字幕校对日志"};if(d.ShowDialog(owner)==true)File.WriteAllText(d.FileName,string.Join(Environment.NewLine,logLines),new UTF8Encoding(true));});
