   files.CollectionChanged+=(s,e)=> {if(e.NewItems!=null)foreach(SubtitleFile f in e.NewItems)f.PropertyChanged+=(a,b)=>NotifyChanged();NotifyChanged();};View.AddHandler(Button.ClickEvent,new RoutedEventHandler((s,e)=>NotifyChanged()),true);
