  }
  void SetProgress(double done,double total,string text) {if(closed)return;var p=Get<ProgressBar>("SubProgress");p.Maximum=Math.Max(1,total);p.Value=Math.Max(0,Math.Min(total,done));Get<TextBlock>("SubProgressText").Text=text+" · "+Math.Round(p.Value/p.Maximum*100)+"%";}
  void MoveSubtitle(int delta) {var list=Get<DataGrid>("SubtitleFiles").Items.Cast<SubtitleFile>().ToList();if(list.Count==0)return;int at=list.IndexOf(current),next=Math.Max(0,Math.Min(list.Count-1,at+delta));Get<DataGrid>("SubtitleFiles").SelectedItem=list[next];Get<DataGrid>("SubtitleFiles").ScrollIntoView(list[next]);NotifyChanged();}
  public void RefreshVideoLinks(bool force=false) {int linked=0;foreach(var file in files){if(file.ManualVideo&&!force&&File.Exists(file.VideoPath))continue;string match=FindVideo(file.Path);if(!string.IsNullOrEmpty(match)&&file.VideoPath!=match){file.VideoPath=match;file.ManualVideo=false;file.Refresh();linked++;if(current==file){var cue=Get<DataGrid>("Cues").SelectedItem as Cue;LoadVideo();if(cue!=null)ShowCue(cue,Get<DataGrid>("SubtitleIssues").SelectedItem as SubtitleIssue);}}}if(force)Status("已补充关联 "+linked+" 集。重名或没有匹配的视频可手动关联。");if(linked>0)NotifyChanged();}
  static int BatchCount(SubtitleFile file) {int count=0,length=0,part=0;foreach(var cue in file.Cues){if(count>=35||length+cue.Original.Length>4500){part++;count=0;length=0;}count++;length+=cue.Original.Length;}return part+(count>0?1:0);}
  void BeginUndoGroup() {undoGroup=current==null?null:SnapshotUndo(current);}
  void EndUndoGroup() {if(undoGroup!=null) {undo.Add(undoGroup);undoGroup=null;}NotifyChanged();}
  UndoEntry SnapshotUndo(SubtitleFile file) {return new UndoEntry {File=file.Path,ManualReview=file.ManualReview,Cues=file.Cues.Select(c=>new UndoCue {Id=c.Id,Corrected=c.Corrected}).ToList(),Issues=file.Issues.Select((x,i)=>new UndoIssue {Index=i,State=x.State,Accepted=x.Accepted}).ToList()};}
  void RecordUndo(SubtitleIssue issue) {if(current!=null&&undoGroup==null)undo.Add(SnapshotUndo(current));if(undo.Count>100)undo.RemoveAt(0);}
  void UndoLast() {if(IsBusy||undo.Count==0){Status("没有可撤销的字幕修改。");return;}var change=undo[undo.Count-1];undo.RemoveAt(undo.Count-1);var file=files.FirstOrDefault(x=>x.Path==change.File);if(file==null)return;foreach(var c in change.Cues){var cue=file.Cues.FirstOrDefault(x=>x.Id==c.Id);if(cue!=null){cue.Corrected=c.Corrected;cue.Refresh();}}foreach(var old in change.Issues)if(old.Index<file.Issues.Count){var x=file.Issues[old.Index];x.State=old.State;x.Accepted=old.Accepted;x.Refresh();}file.ManualReview=change.ManualReview;Select(file);foreach(var cue in file.Cues)RefreshCueState(cue);file.Refresh();Status("已撤销上一次采纳操作，原字幕文件仍未修改。");}
  void ShowChanges() {var rows=files.SelectMany(f=>f.Cues.Where(c=>c.Corrected!=null&&c.Corrected!=c.Original).Select(c=>new {字幕文件=f.Name,序号=c.Number,开始时间=Util.Time(c.Start),原文=c.Original,修改后=c.Text})).ToList();var w=FrameWindows.Dialog(owner,"字幕修改预览 · "+rows.Count+" 条",1050,620);w.Content=new DataGrid {ItemsSource=rows,AutoGenerateColumns=true,IsReadOnly=true,Margin=new Thickness(12),CanUserAddRows=false};w.Show();}
  public SubtitleProject CaptureProject() {return new SubtitleProject {PanelWidths=PanelLayout.Capture(Get<Grid>("SubtitleColumns")),ScriptPath=scriptPath,Script=script,ScriptHash=ProjectStore.TextHash(script),Selected=current==null?null:current.Path,Nouns=Nouns,Logs=logLines.ToList(),Undo=undo.ToList(),Multi=Get<CheckBox>("MultiDialogs").IsChecked==true,BatchFiles=ParseCount("BatchFiles",1,100,5),Dialogs=ParseCount("DialogCount",1,16,2),Files=files.Select(f=>new SavedSubtitle {Path=f.Path,Hash=f.ContentHash,VideoPath=f.VideoPath,ManualVideo=f.ManualVideo,Status=f.Status=="校对中"?"上次中断，待校对":f.Status,Completed=f.Completed,ManualReview=f.ManualReview,Cues=f.Cues.Select(c=>new SavedCue {Id=c.Id,Corrected=c.Corrected,State=c.ReviewState}).ToList(),Issues=f.Issues.Select(x=>new SavedIssue {CueId=x.Cue.Id,State=x.State,Accepted=x.Accepted,OriginalTerm=x.OriginalTerm,SuggestedTerm=x.SuggestedTerm,Reason=x.Reason,Evidence=x.Evidence}).ToList()}).ToList()};}
  int ParseCount(string name,int min,int max,int fallback) {int n;return int.TryParse(Get<TextBox>(name).Text,out n)&&n>=min&&n<=max?n:fallback;}
  public async Task RestoreProject(SubtitleProject state) {if(state==null)return;PanelLayout.Restore(Get<Grid>("SubtitleColumns"),state.PanelWidths);files.Clear();undo.Clear();Nouns=state.Nouns??new List<Noun>();script=state.Script??"";scriptPath=state.ScriptPath??"";Get<TextBox>("ScriptPathBox").Text=scriptPath;bool scriptChanged=false;if(File.Exists(scriptPath)) {var fresh=await Task.Run(()=>SubtitleIO.Script(scriptPath));if(ProjectStore.TextHash(fresh)!=state.ScriptHash){script=fresh;Nouns.Clear();scriptChanged=true;}}Get<TextBlock>("ScriptInfo").Text="剧本："+Path.GetFileName(scriptPath)+" · "+script.Length+" 字符";Get<TextBlock>("NounCount").Text="名词表："+Nouns.Count+" 项";
   foreach(var saved in state.Files)try {var f=await Task.Run(()=>SubtitleIO.Read(saved.Path));f.VideoPath=saved.VideoPath;f.ManualVideo=saved.ManualVideo;bool same=f.ContentHash==saved.Hash&&!scriptChanged;if(same) {f.Completed=saved.Completed;f.ManualReview=saved.ManualReview;f.Status=saved.Status;foreach(var c in saved.Cues){var cue=f.Cues.FirstOrDefault(x=>x.Id==c.Id);if(cue!=null){cue.Corrected=c.Corrected;cue.ReviewState=c.State;}}foreach(var x in saved.Issues) {var cue=f.Cues.FirstOrDefault(c=>c.Id==x.CueId);if(cue!=null)f.Issues.Add(new SubtitleIssue {Cue=cue,State=x.State,Accepted=x.Accepted,OriginalTerm=x.OriginalTerm,SuggestedTerm=x.SuggestedTerm,Reason=x.Reason,Evidence=x.Evidence});}}else f.Status="源文件已变更，待校对";files.Add(f);}catch(Exception ex){Log("未恢复 "+Path.GetFileName(saved.Path)+"："+ex.Message);}
   if(!scriptChanged)undo.AddRange((state.Undo??new List<UndoEntry>()).Where(x=>files.Any(f=>f.Path==x.File&&f.Completed)));logLines.Clear();logLines.AddRange((state.Logs??new List<string>()).Take(1500));Get<TextBox>("LogText").Text=string.Join(Environment.NewLine,logLines);Get<CheckBox>("MultiDialogs").IsChecked=state.Multi;Get<TextBox>("BatchFiles").Text=state.BatchFiles.ToString();Get<TextBox>("DialogCount").Text=state.Dialogs.ToString();var selected=files.FirstOrDefault(x=>x.Path==state.Selected)??files.FirstOrDefault();Get<DataGrid>("SubtitleFiles").SelectedItem=selected;Select(selected);SetProgress(files.Count(f=>f.Completed),Math.Max(1,files.Count),"已恢复 "+files.Count+" 集字幕");Status(scriptChanged?"项目已恢复；剧本已修改，名词表和校对结果需要重新生成。":"字幕项目与审核记录已恢复。");}
